const body = $input.first().json.body;
const headers = $input.first().json.headers;

// Handle verification challenge
if ($input.first().json.query?.['hub.challenge']) {
  return [{ json: { challenge: $input.first().json.query['hub.challenge'], is_verification: true } }];
}

const messages = [];

if (body.object === 'instagram' || body.object === 'page') {
  const entries = body.entry || [];

  for (const entry of entries) {
    // Direct messages
    const messaging = entry.messaging || [];
    for (const msg of messaging) {
      if (msg.message?.text) {
        messages.push({
          type: 'dm',
          text: msg.message.text,
          sender_id: msg.sender?.id,
          timestamp: msg.timestamp
        });
      }
    }

    // Comments
    const changes = entry.changes || [];
    for (const change of changes) {
      if (change.field === 'comments' && change.value?.text) {
        messages.push({
          type: 'comment',
          text: change.value.text,
          sender_id: change.value?.from?.id,
          post_id: change.value?.media?.id,
          timestamp: change.value?.timestamp
        });
      }
    }
  }
}

return [{ json: { messages, count: messages.length, is_verification: false } }];

const { messages } = $input.first().json;

const COMPLAINT_KEYWORDS = [
  'problema', 'reclamação', 'horrível', 'péssimo', 'ruim', 'demora', 'atraso',
  'não chegou', 'errado', 'quebrado', 'defeito', 'cancelar', 'reembolso',
  'devolver', 'decepcionada', 'decepcionado', 'insatisfeito', 'não funciona',
  'cadê', 'cadê meu', 'sumiu', 'roubaram', 'golpe', 'fraude', 'procon'
];

const complaints = [];

for (const msg of messages) {
  const lower = msg.text.toLowerCase();
  const matched = COMPLAINT_KEYWORDS.filter(kw => lower.includes(kw));

  if (matched.length > 0) {
    const criticalWords = ['fraude', 'golpe', 'roubaram', 'procon'];
    let severity = 'low';
    if (criticalWords.some(w => lower.includes(w))) severity = 'critical';
    else if (matched.length >= 4) severity = 'high';
    else if (matched.length >= 2) severity = 'medium';

    complaints.push({
      ...msg,
      matched_keywords: matched,
      severity
    });
  }
}

const hasCriticalOrHigh = complaints.some(c => c.severity === 'critical' || c.severity === 'high');

return [{ json: { complaints, count: complaints.length, has_high_priority: hasCriticalOrHigh } }];
